contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint val, uint val2) public payable {
        require(true);

        bool firstReverted;
        c.SetMinSum(val); bool __rev0 = __ESBMC_reverted(); if (__rev0) { firstReverted = true; } else { firstReverted = false; }

        uint minSumAfterFirst = c.MinSum(); if (__ESBMC_reverted()) return;

        bool secondReverted;
        c.SetMinSum(val2); bool __rev1 = __ESBMC_reverted(); if (__rev1) { secondReverted = true; } else { secondReverted = false; }

        uint minSumAfterSecond = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(
            !firstReverted &&
            minSumAfterFirst == val &&
            !secondReverted &&
            minSumAfterSecond == val2
        );
    }

    receive() external payable {}
}

